import { tags } from "typia";

/**
 * Daily registration count for a specific date.
 *
 * Represents user registrations aggregated at the daily level, showing how many
 * new users registered on a particular date. Part of the registration trend
 * analysis used to visualize registration patterns and growth trends over the
 * 30-day historical period.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IRegistrationTrendDay = {
  /**
   * The calendar date for this trend entry. Format: YYYY-MM-DD. Represents
   * the day on which the registration count was recorded.
   */
  date: string & tags.Format<"date">;

  /**
   * Number of new user registrations on this specific date. Shows daily
   * registration volume and helps identify registration pattern peaks and
   * valleys.
   */
  count: number & tags.Type<"int32">;
};
